void M2L_2(double x, double y, double z, double * __restrict M, double * __restrict L) {
double Rinv = 1.0 / sqrt(x*x + y*y + z*z);
double D[9];
double Dtmp0 = std::pow(Rinv, 3);
double Dtmp1 = 3*std::pow(Rinv, 2);
double Dtmp2 = std::pow(Rinv, 5);
double Dtmp3 = 3*Dtmp2*x;
D[0] = -Dtmp0*x;
D[1] = -Dtmp0*y;
D[2] = -Dtmp0*z;
D[3] = Dtmp0*(Dtmp1*std::pow(x, 2) - 1);
D[4] = Dtmp3*y;
D[5] = Dtmp3*z;
D[6] = Dtmp0*(Dtmp1*std::pow(y, 2) - 1);
D[7] = 3*Dtmp2*y*z;
D[8] = -D[3] - D[6];
#pragma omp atomic
L[0] += D[0]*M[0] + D[1]*M[1] + D[2]*M[2] + D[3]*M[3] + D[4]*M[4] + D[5]*M[5] + D[6]*M[6] + D[7]*M[7] + D[8]*M[8];
#pragma omp atomic
L[1] += D[3]*M[0] + D[4]*M[1] + D[5]*M[2];
#pragma omp atomic
L[2] += D[4]*M[0] + D[6]*M[1] + D[7]*M[2];
#pragma omp atomic
L[3] += D[5]*M[0] + D[7]*M[1] + D[8]*M[2];

}

