void M2P_2(double x, double y, double z, double * __restrict M, double * __restrict F) {
double Rinv = 1.0 / sqrt(x*x + y*y + z*z);
double Ftmp0 = std::pow(Rinv, 3);
double Ftmp1 = -M[0];
double Ftmp2 = std::pow(Rinv, 2);
double Ftmp3 = 3*Ftmp2;
double Ftmp4 = Ftmp3*y;
double Ftmp5 = Ftmp3*z;
double Ftmp6 = 5*Ftmp2;
double Ftmp7 = Ftmp6*z;
double Ftmp8 = z*(Ftmp7*M[8] - M[2]);
double Ftmp9 = Ftmp6*y;
double Ftmp10 = Ftmp9*M[6];
double Ftmp11 = Ftmp7*M[7] - M[1];
double Ftmp12 = y*(Ftmp10 + Ftmp11);
double Ftmp13 = Ftmp6*x*M[3];
double Ftmp14 = Ftmp9*M[4];
double Ftmp15 = Ftmp1 + Ftmp7*M[5];
double Ftmp16 = Ftmp14 + Ftmp15;
double Ftmp17 = Ftmp3*x;
double Ftmp18 = -Ftmp8 + M[3];
#pragma omp atomic
F[0] += Ftmp0*(-Ftmp1 - Ftmp17*(-Ftmp12 - Ftmp8 - x*(Ftmp13 + Ftmp16) + 3*M[3] + M[6] + M[8]) - Ftmp4*M[4] - Ftmp5*M[5]);
#pragma omp atomic
F[1] += Ftmp0*(Ftmp17*(Ftmp13*y + Ftmp16*y - M[4]) - Ftmp4*(-Ftmp12 + Ftmp18 + 3*M[6] + M[8]) - Ftmp5*M[7] + M[1]);
#pragma omp atomic
F[2] += Ftmp0*(Ftmp17*(Ftmp13*z + Ftmp14*z + Ftmp15*z - M[5]) + Ftmp4*(Ftmp10*z + Ftmp11*z - M[7]) - Ftmp5*(Ftmp18 + M[6] + 3*M[8]) + M[2]);

}

