void M2Pc_2(double x, double y, double z, double * __restrict M, double * __restrict F) {
double Rinv = 1.0 / sqrt(x*x + y*y + z*z);
double Ftmp0 = std::pow(Rinv, 3);
double Ftmp1 = -M[0];
double Ftmp2 = std::pow(Rinv, 2);
double Ftmp3 = 3*Ftmp2;
double Ftmp4 = Ftmp3*y;
double Ftmp5 = Ftmp3*z;
double Ftmp6 = z*M[2];
double Ftmp7 = 5*Ftmp2;
double Ftmp8 = Ftmp7*y;
double Ftmp9 = Ftmp8*M[6];
double Ftmp10 = Ftmp7*z;
double Ftmp11 = Ftmp10*M[7] - M[1];
double Ftmp12 = -y*(Ftmp11 + Ftmp9);
double Ftmp13 = Ftmp7*x*M[3];
double Ftmp14 = Ftmp8*M[4];
double Ftmp15 = Ftmp1 + Ftmp10*M[5];
double Ftmp16 = Ftmp14 + Ftmp15;
double Ftmp17 = Ftmp3*x;
double Ftmp18 = Ftmp6 + M[3];
#pragma omp atomic
F[0] += Ftmp0*(-Ftmp1 - Ftmp17*(Ftmp12 + Ftmp6 - x*(Ftmp13 + Ftmp16) + 3*M[3] + M[6]) - Ftmp4*M[4] - Ftmp5*M[5]);
#pragma omp atomic
F[1] += Ftmp0*(Ftmp17*(Ftmp13*y + Ftmp16*y - M[4]) - Ftmp4*(Ftmp12 + Ftmp18 + 3*M[6]) - Ftmp5*M[7] + M[1]);
#pragma omp atomic
F[2] += Ftmp0*(Ftmp17*(Ftmp13*z + Ftmp14*z + Ftmp15*z - M[5]) + Ftmp4*(Ftmp11*z + Ftmp9*z - M[7]) - Ftmp5*(Ftmp18 + M[6]) + M[2]);

}

void M2Lc_2(double x, double y, double z, double * __restrict M, double * __restrict L) {
double Rinv = 1.0 / sqrt(x*x + y*y + z*z);
double D[9];
double Dtmp0 = std::pow(Rinv, 3);
double Dtmp1 = 3*std::pow(Rinv, 2);
double Dtmp2 = std::pow(Rinv, 5);
double Dtmp3 = 3*Dtmp2*x;
D[0] = -Dtmp0*x;
D[1] = -Dtmp0*y;
D[2] = -Dtmp0*z;
D[3] = Dtmp0*(Dtmp1*std::pow(x, 2) - 1);
D[4] = Dtmp3*y;
D[5] = Dtmp3*z;
D[6] = Dtmp0*(Dtmp1*std::pow(y, 2) - 1);
D[7] = 3*Dtmp2*y*z;
D[8] = -D[3] - D[6];
#pragma omp atomic
L[0] += D[0]*M[0] + D[1]*M[1] + D[2]*M[2] + D[3]*M[3] + D[4]*M[4] + D[5]*M[5] + D[6]*M[6] + D[7]*M[7];
#pragma omp atomic
L[1] += D[3]*M[0] + D[4]*M[1] + D[5]*M[2];
#pragma omp atomic
L[2] += D[4]*M[0] + D[6]*M[1] + D[7]*M[2];
#pragma omp atomic
L[3] += D[5]*M[0] + D[7]*M[1] + D[8]*M[2];

}

